package io.ecosync.mcp;
import java.util.Set;
public class McpFailure extends RuntimeException {
 private static final Set<String> CODES=Set.of("MCP_UNAVAILABLE","MCP_AUTHENTICATION_FAILED","MCP_TIMEOUT","MCP_CANCELLED","MCP_DESTINATION_DENIED","MCP_REDIRECT_DENIED","MCP_UNSUPPORTED_PROTOCOL","MCP_SCHEMA_CHANGED","MCP_SCHEMA_UNSUPPORTED","MCP_SCHEMA_TOO_LARGE","MCP_INVALID_ARGUMENTS","MCP_ARGUMENTS_TOO_LARGE","MCP_RESPONSE_TOO_LARGE","MCP_RESPONSE_COMPLEXITY","MCP_INVALID_RESPONSE","MCP_DISCOVERY_LIMIT","MCP_CONCURRENCY_LIMIT","MCP_CLIENT_RETIRED","MCP_TOOL_FAILED","MCP_CLIENT_LIMIT","MCP_CONNECTION_BUSY","MCP_DISABLED");
 private final String code;
 public McpFailure(String code){super(CODES.contains(code)?code:"MCP_UNAVAILABLE");this.code=CODES.contains(code)?code:"MCP_UNAVAILABLE";}
 public String code(){return code;}
 public int status(){return switch(code){case "MCP_DESTINATION_DENIED","MCP_INVALID_ARGUMENTS","MCP_SCHEMA_UNSUPPORTED","MCP_UNSUPPORTED_PROTOCOL","MCP_AUTHENTICATION_FAILED"->422;case "MCP_SCHEMA_CHANGED","MCP_CLIENT_RETIRED","MCP_CANCELLED"->409;case "MCP_CONCURRENCY_LIMIT","MCP_CLIENT_LIMIT"->429;case "MCP_ARGUMENTS_TOO_LARGE","MCP_RESPONSE_TOO_LARGE","MCP_SCHEMA_TOO_LARGE"->413;case "MCP_TIMEOUT"->504;case "MCP_DISABLED"->503;default->502;};}
 public String safeMessage(){return switch(code){case "MCP_AUTHENTICATION_FAILED"->"The MCP server rejected its configured credential.";case "MCP_TIMEOUT"->"The MCP operation exceeded its deadline.";case "MCP_CANCELLED"->"The MCP operation was cancelled.";case "MCP_DESTINATION_DENIED","MCP_REDIRECT_DENIED"->"Operator destination policy rejected this connection.";case "MCP_UNSUPPORTED_PROTOCOL"->"The server does not support the selected tested protocol policy.";case "MCP_SCHEMA_CHANGED"->"The remote capability changed; discover and approve its current schema.";case "MCP_SCHEMA_UNSUPPORTED","MCP_SCHEMA_TOO_LARGE"->"This capability schema exceeds the supported safe subset or size.";case "MCP_INVALID_ARGUMENTS"->"Arguments do not match the approved input schema.";case "MCP_CLIENT_RETIRED"->"This connection revision or lease is no longer usable.";case "MCP_DISABLED"->"Native MCP management is disabled in this deployment.";default->"The MCP operation could not be completed. Review its status and retry when available.";};}
}
